{
  "title": "Terms of Use for Al-Qimam Mobile Application",
  "planted": [
    {
      "slot": "p1",
      "text": "To enhance user experience and deliver tailored promotional offers, our platform processes sensitive categories including health conditions, religious preferences, and biometric identifiers, with unrestricted access granted across all operational departments."
    },
    {
      "slot": "p2",
      "text": "By continuing to access or use the application after the publication of any updates, the user provides definitive and irrevocable agreement to all data processing activities, and consent cannot be withdrawn or modified for the duration of the active subscription period."
    },
    {
      "slot": "p3",
      "text": "The company reserves the right to utilize all collected information for any operational, commercial, or developmental purpose deemed appropriate now or in the future, including purposes that may be determined at a later stage."
    },
    {
      "slot": "p4",
      "text": "Prior to completing the account registration process, users can review the comprehensive privacy notice detailing the precise categories of collected data, processing methods, storage durations, destruction protocols, and available user rights."
    },
    {
      "slot": "p5",
      "text": "Users maintain the right to submit requests to access, correct, update, or complete their information, as well as request the destruction of records that are no longer necessary for the initial operational scope."
    },
    {
      "slot": "p6",
      "text": "The application shall gather information in an adequate quantity that is reasonably sufficient to support the general functionality and performance objectives of the digital platform."
    }
  ],
  "neutral": [
    "All subscription fees are billed in advance on a recurring monthly basis and are strictly non-refundable under any circumstances following the completion of the transaction.",
    "The term of this agreement commences upon successful account creation and remains in full force until terminated by either party in accordance with the cancellation procedures set forth within the application interface.",
    "The company shall bear no liability for any indirect, incidental, or consequential damages arising out of or in connection with the use or inability to use the mobile application services.",
    "This agreement shall be governed by and construed in accordance with the applicable laws in the jurisdiction where the company maintains its principal place of business, without regard to conflict of law principles.",
    "All intellectual property rights, including trademarks, logos, software code, and textual content embedded within the application, remain the exclusive property of Al-Qimam Technologies and may not be reproduced without explicit written authorization."
  ]
}
